-- =====================================================================
-- StreamHub Database Schema
-- Group ID: 2026-Y2-S1-MLB-B2G2-07
--
-- This is the single source of truth for all six members' local
-- StreamHubDB instances. Every member runs this script once against
-- their own local Microsoft SQL Server to get an identical schema.
--
-- All primary keys are UUID (UNIQUEIDENTIFIER), generated by the
-- Spring Boot / Hibernate layer (GenerationType.UUID) rather than the
-- database. This is what makes the daily data-sync process safe: data
-- created independently on six different machines never collides on
-- an ID when it's merged together later.
--
-- Dependency order (also used by the data-sync import script):
-- User -> Category -> Video -> Playlist -> PlaylistVideo ->
-- Comment -> Like -> Report -> WatchHistory
--
-- Any change to this file must go through a pull request and be
-- reviewed before anyone applies it to their local database.
-- =====================================================================

-- ---------------------------------------------------------------------
-- USER
-- Referenced by nearly every other table, so it has no dependencies
-- of its own and sits first.
-- ---------------------------------------------------------------------
CREATE TABLE [User] (
    user_id         UNIQUEIDENTIFIER   NOT NULL PRIMARY KEY,
    username        NVARCHAR(50)       NOT NULL,
    email           NVARCHAR(100)      NOT NULL,
    password_hash   NVARCHAR(255)      NOT NULL,
    role            NVARCHAR(20)       NOT NULL,
    created_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT UQ_User_Username UNIQUE (username),
    CONSTRAINT UQ_User_Email UNIQUE (email),
    CONSTRAINT CK_User_Role CHECK (role IN ('USER', 'CONTENT_MODERATOR', 'ADMINISTRATOR'))
);
GO

-- ---------------------------------------------------------------------
-- CATEGORY
-- No foreign keys of its own; Video depends on this, so it comes
-- before Video.
-- ---------------------------------------------------------------------
CREATE TABLE Category (
    category_id     UNIQUEIDENTIFIER   NOT NULL PRIMARY KEY,
    name            NVARCHAR(50)       NOT NULL,
    description     NVARCHAR(255)      NULL,
    created_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT UQ_Category_Name UNIQUE (name)
);
GO

-- ---------------------------------------------------------------------
-- VIDEO
-- Owned by Video Upload & Management. Almost every other function
-- references this table.
-- ---------------------------------------------------------------------
CREATE TABLE Video (
    video_id            UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    uploader_id         UNIQUEIDENTIFIER  NOT NULL,
    category_id         UNIQUEIDENTIFIER  NULL,
    title               NVARCHAR(150)     NOT NULL,
    description         NVARCHAR(MAX)     NULL,
    file_path           NVARCHAR(500)     NOT NULL,
    thumbnail_path      NVARCHAR(500)     NULL,
    duration_seconds    INT               NULL,
    visibility          NVARCHAR(20)      NOT NULL DEFAULT 'PUBLIC',
    view_count          INT               NOT NULL DEFAULT 0,
    created_at          DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at          DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Video_Uploader FOREIGN KEY (uploader_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Video_Category FOREIGN KEY (category_id) REFERENCES Category(category_id),
    CONSTRAINT CK_Video_Duration CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
    CONSTRAINT CK_Video_Visibility CHECK (visibility IN ('PUBLIC','PRIVATE','UNLISTED'))
);
GO
CREATE INDEX IX_Video_Uploader ON Video(uploader_id);
CREATE INDEX IX_Video_Category ON Video(category_id);
GO

-- ---------------------------------------------------------------------
-- PLAYLIST
-- ---------------------------------------------------------------------
CREATE TABLE Playlist (
    playlist_id     UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    owner_id        UNIQUEIDENTIFIER  NOT NULL,
    name            NVARCHAR(100)     NOT NULL,
    description     NVARCHAR(255)     NULL,
    is_public       BIT               NOT NULL DEFAULT 1,
    created_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at      DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Playlist_Owner FOREIGN KEY (owner_id) REFERENCES [User](user_id)
);
GO
CREATE INDEX IX_Playlist_Owner ON Playlist(owner_id);
GO

-- ---------------------------------------------------------------------
-- PLAYLIST_VIDEO (join table for the many-to-many between Playlist
-- and Video; keeps track of ordering within a playlist)
-- ---------------------------------------------------------------------
CREATE TABLE PlaylistVideo (
    playlist_video_id  UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    playlist_id         UNIQUEIDENTIFIER  NOT NULL,
    video_id             UNIQUEIDENTIFIER  NOT NULL,
    position             INT               NOT NULL,
    added_at             DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at           DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_PlaylistVideo_Playlist FOREIGN KEY (playlist_id) REFERENCES Playlist(playlist_id),
    CONSTRAINT FK_PlaylistVideo_Video FOREIGN KEY (video_id) REFERENCES Video(video_id),
    CONSTRAINT UQ_PlaylistVideo UNIQUE (playlist_id, video_id)
);
GO
CREATE INDEX IX_PlaylistVideo_Playlist ON PlaylistVideo(playlist_id);
CREATE INDEX IX_PlaylistVideo_Video ON PlaylistVideo(video_id);
GO

-- ---------------------------------------------------------------------
-- COMMENT
-- parent_comment_id is self-referencing and nullable, to support
-- threaded replies. A top-level comment has parent_comment_id = NULL.
-- ---------------------------------------------------------------------
CREATE TABLE Comment (
    comment_id          UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    video_id             UNIQUEIDENTIFIER  NOT NULL,
    user_id               UNIQUEIDENTIFIER  NOT NULL,
    parent_comment_id   UNIQUEIDENTIFIER  NULL,
    content               NVARCHAR(1000)    NOT NULL,
    created_at           DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at           DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Comment_Video FOREIGN KEY (video_id) REFERENCES Video(video_id),
    CONSTRAINT FK_Comment_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Comment_Parent FOREIGN KEY (parent_comment_id) REFERENCES Comment(comment_id)
);
GO
CREATE INDEX IX_Comment_Video ON Comment(video_id);
CREATE INDEX IX_Comment_User ON Comment(user_id);
CREATE INDEX IX_Comment_Parent ON Comment(parent_comment_id);
GO

-- ---------------------------------------------------------------------
-- LIKE (video likes; one like per user per video)
-- ---------------------------------------------------------------------
CREATE TABLE [Like] (
    like_id       UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id        UNIQUEIDENTIFIER  NOT NULL,
    video_id       UNIQUEIDENTIFIER  NOT NULL,
    created_at     DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at     DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Like_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Like_Video FOREIGN KEY (video_id) REFERENCES Video(video_id),
    CONSTRAINT UQ_Like_UserVideo UNIQUE (user_id, video_id)
);
GO
CREATE INDEX IX_Like_Video ON [Like](video_id);
GO

-- ---------------------------------------------------------------------
-- REPORT
-- A report targets either a video or a comment, never both and never
-- neither -- enforced by CK_Report_Target.
-- ---------------------------------------------------------------------
CREATE TABLE Report (
    report_id       UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    reporter_id      UNIQUEIDENTIFIER  NOT NULL,
    video_id          UNIQUEIDENTIFIER  NULL,
    comment_id        UNIQUEIDENTIFIER  NULL,
    reason            NVARCHAR(50)      NOT NULL,
    description        NVARCHAR(500)     NULL,
    status              NVARCHAR(20)      NOT NULL DEFAULT 'PENDING',
    reviewed_by         UNIQUEIDENTIFIER  NULL,
    created_at           DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    reviewed_at          DATETIME2         NULL,
    updated_at           DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_Report_Reporter FOREIGN KEY (reporter_id) REFERENCES [User](user_id),
    CONSTRAINT FK_Report_Video FOREIGN KEY (video_id) REFERENCES Video(video_id),
    CONSTRAINT FK_Report_Comment FOREIGN KEY (comment_id) REFERENCES Comment(comment_id),
    CONSTRAINT FK_Report_Reviewer FOREIGN KEY (reviewed_by) REFERENCES [User](user_id),
    CONSTRAINT CK_Report_Reason CHECK (reason IN ('SPAM','HARASSMENT','COPYRIGHT','INAPPROPRIATE','MISINFORMATION','OTHER')),
    CONSTRAINT CK_Report_Status CHECK (status IN ('PENDING','REVIEWED','RESOLVED','DISMISSED')),
    CONSTRAINT CK_Report_Target CHECK (
        (video_id IS NOT NULL AND comment_id IS NULL) OR
        (video_id IS NULL AND comment_id IS NOT NULL)
    )
);
GO
CREATE INDEX IX_Report_Status ON Report(status);
CREATE INDEX IX_Report_Video ON Report(video_id);
CREATE INDEX IX_Report_Comment ON Report(comment_id);
GO

-- ---------------------------------------------------------------------
-- WATCH_HISTORY
-- A log table -- the same user/video pair can appear many times
-- (rewatches), so there is no uniqueness constraint here.
-- ---------------------------------------------------------------------
CREATE TABLE WatchHistory (
    watch_history_id         UNIQUEIDENTIFIER  NOT NULL PRIMARY KEY,
    user_id                   UNIQUEIDENTIFIER  NOT NULL,
    video_id                   UNIQUEIDENTIFIER  NOT NULL,
    watched_at                 DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    watch_duration_seconds     INT               NULL,
    updated_at                  DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT FK_WatchHistory_User FOREIGN KEY (user_id) REFERENCES [User](user_id),
    CONSTRAINT FK_WatchHistory_Video FOREIGN KEY (video_id) REFERENCES Video(video_id)
);
GO
CREATE INDEX IX_WatchHistory_User ON WatchHistory(user_id, watched_at DESC);
CREATE INDEX IX_WatchHistory_Video ON WatchHistory(video_id);
GO

-- ---------------------------------------------------------------------
-- SYNC_LOG
-- Local-only bookkeeping table. Tracks which data-sync/*.sql files
-- from teammates have already been applied to THIS machine, so the
-- daily-sync script never double-applies a file. This table is never
-- exported and never appears in a data-sync file itself.
-- ---------------------------------------------------------------------
CREATE TABLE SyncLog (
    sync_log_id     INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    file_name        NVARCHAR(255)     NOT NULL,
    applied_at        DATETIME2         NOT NULL DEFAULT SYSUTCDATETIME(),
    CONSTRAINT UQ_SyncLog_FileName UNIQUE (file_name)
);
GO

-- ---------------------------------------------------------------------
-- SCHEMA DELTA: AUTH + SECURITY CONFIG
-- ---------------------------------------------------------------------

-- Add new columns to User table
-- Note: Providing default values allows this to run on existing local data
ALTER TABLE [User]
ADD 
    first_name      NVARCHAR(50)   NOT NULL DEFAULT 'Unknown',
    last_name       NVARCHAR(50)   NOT NULL DEFAULT 'Unknown',
    date_of_birth   DATE           NOT NULL DEFAULT '2000-01-01';
GO

-- ---------------------------------------------------------------------
-- REFRESH_TOKEN
-- ---------------------------------------------------------------------
CREATE TABLE RefreshToken (
    id              UNIQUEIDENTIFIER   NOT NULL PRIMARY KEY,
    user_id         UNIQUEIDENTIFIER   NOT NULL,
    token_hash      NVARCHAR(255)      NOT NULL,
    expires_at      DATETIME2          NOT NULL,
    created_at      DATETIME2          NOT NULL DEFAULT SYSUTCDATETIME(),
    revoked         BIT                NOT NULL DEFAULT 0,
    CONSTRAINT FK_RefreshToken_User FOREIGN KEY (user_id) REFERENCES [User](user_id) ON DELETE CASCADE
);
GO
CREATE INDEX IX_RefreshToken_User ON RefreshToken(user_id);
GO
